package com.chatsystem.user.controller.group;
import com.chatsystem.shared.model.Conversation;import com.chatsystem.shared.service.GroupService;import com.chatsystem.user.navigation.*;import com.chatsystem.user.ui.cell.GroupCell;import javafx.fxml.FXML;import javafx.scene.control.*;
public final class GroupManagementController{private final GroupService groups;private final UserNavigator nav;@FXML private ListView<Conversation> groupList;public GroupManagementController(GroupService g,UserNavigator n){groups=g;nav=n;}@FXML private void initialize(){groupList.setItems(groups.getGroups());groupList.setCellFactory(x->new GroupCell());groupList.setOnMouseClicked(e->{if(e.getClickCount()==2)open();});}@FXML private void open(){var g=groupList.getSelectionModel().getSelectedItem();if(g!=null)nav.navigate(ViewRequest.conversation(UserRoute.GROUP_DETAILS,g.getId()));}@FXML private void create(){nav.showDialog("/fxml/dialogs/create-group.fxml","Create group");}@FXML private void invitations(){nav.navigate(ViewRequest.of(UserRoute.GROUP_INVITATIONS));}}
